"""

    /** Symbol-module (x, y) -> bitmap pixel at that module's centre. */
    private fun centrePx(bmpPx: Int, moduleX: Int, moduleY: Int): Pair<Int, Int> {
        // module n starts at viewBox (4 + n) * 4; +2 lands mid-module.
        val vbX = (4 + moduleX) * 4 + 2
        val vbY = (4 + moduleY) * 4 + 2
        val s = bmpPx / 164f
        return Math.round(vbX * s) to Math.round(vbY * s)
    }

    @Test
    fun parsesViewBoxAndModules() {
        assertEquals(164, QrSvg.viewBoxDim(fixture))
        val mods = QrSvg.modules(fixture)
        assertNotNull(mods)
        assertTrue("569 dark modules expected, got " + mods!!.size, mods.size == 569)
        for (m in mods) {
            assertTrue(m.x >= 0 && m.y >= 0 && m.w > 0 && m.h > 0)
            assertTrue(m.x + m.w <= 164 && m.y + m.h <= 164)
        }
    }

    @Test
    fun rejectsNonQrSvg() {
        assertNull(QrSvg.viewBoxDim("<html>not an svg</html>"))
        // a module sticking out of the viewBox is not a QR we trust
        assertNull(QrSvg.modules("""<svg viewBox="0 0 100 100"><g fill="#111"><rect x="98" y="0" width="4" height="4"/></g></svg>"""))
    }

    @Test
    fun rendersFindersAndQuietZone() {
        // 656 = 164 * 4: integer scale, module edges land on exact pixels.
        val bmp = QrSvg.render(fixture, 656)
        assertNotNull(bmp)
        assertEquals(656, bmp!!.width)
        assertEquals(656, bmp.height)

        fun px(x: Int, y: Int) = bmp.getPixel(x, y)

        // quiet zone: the outer border must be pure white
        for (p in listOf(0 to 0, 655 to 0, 0 to 655, 655 to 655, 327 to 3)) {
            assertEquals("quiet zone at " + p, 0xFFFFFFFF.toInt(), px(p.first, p.second))
        }

        // top-left finder: dark border (module 0,0), light ring (1,1), dark core (3,3)
        val dark = 0xFF111111.toInt()
        var c = centrePx(656, 0, 0); assertEquals("finder border", dark, px(c.first, c.second))
        c = centrePx(656, 1, 1); assertEquals("finder light ring", 0xFFFFFFFF.toInt(), px(c.first, c.second))
        c = centrePx(656, 3, 3); assertEquals("finder core", dark, px(c.first, c.second))

        // top-right finder (module 26..32): border at (32,0)
        c = centrePx(656, 32, 0); assertEquals("top-right finder", dark, px(c.first, c.second))
        // bottom-left finder: border at (0,32)
        c = centrePx(656, 0, 32); assertEquals("bottom-left finder", dark, px(c.first, c.second))
    }
